"""Refresh local-file downloads after editing the SVG templates (no dependencies)."""
from pathlib import Path
import json

root = Path(__file__).resolve().parent.parent
templates = {
    path.stem: path.read_text(encoding="utf-8")
    for path in sorted((root / "assets/templates").glob("*.svg"))
}
output = root / "assets/js/template-downloads.js"
output.write_text(
    "// Generated by scripts/sync-templates.py. Edit the SVG files, then rerun the script.\n"
    "window.SIMPLIKA_TEMPLATES = "
    + json.dumps(templates, ensure_ascii=False, indent=2)
    + ";\n",
    encoding="utf-8",
)
print(f"Updated {len(templates)} template downloads.")
